/* eslint-disable prefer-promise-reject-errors */
import _ from 'lodash'
import { useEffect } from 'react'
import {
  Form,
  Input,
  Switch,
  Row, Col,
  Button,
  InputNumber,
  notification,
  Spin,
  Modal,
  Select
} from 'antd'
import { connect } from 'react-redux'
import { useParams, useHistory } from 'react-router-dom'

import serviceActions from '../../redux/serviceCenter/actions'
import errorActions from '../../../redux/error/actions'
import loadingActions from '../../../redux/loading/actions'

import { alphanumeric } from '../../../constants/validation-regex'

import { CreateBranchContainer, FormContainer } from './serviceCenterDetailStyle'

const {
  getServiceCenterBrandList,
  getServiceCenterDetails,
  resetServiceCenterRedux,
  updateServiceCenterBranch,
  createServiceCenterBranch,
  getServiceCenterBranchDetails
} = serviceActions

const {
  resetErrorRedux
} = errorActions

const {
  resetLoadingRedux
} = loadingActions

const Item = Form.Item
const Option = Select.Option

const DISABLE_SERVICE_CENTER_BRAND_FLOW = process.env.REACT_APP_DISABLE_SERVICE_CENTER_BRAND_FLOW === 'true'

const formDetails = ({ isEditMode, brandList }) => {
  return ([
    {
      label: 'Branch Code',
      name: 'branch_code',
      disabled: !!isEditMode,
      required: true,
      validator: (_, value) => {
        if (alphanumeric.test(value)) {
          return Promise.resolve()
        }
        return Promise.reject('Branch code should be alphanumeric')
      }
    },
    {
      label: 'Branch Name',
      name: 'name',
      required: true
    },
    {
      label: 'Region',
      name: 'region',
      required: true
    },
    {
      label: 'City',
      name: 'city',
      required: true
    },
    {
      label: 'County',
      name: 'county',
      required: true
    },
    {
      label: 'Province',
      name: 'province',
      required: true
    },
    {
      label: 'Postal Code',
      name: 'postal_code',
      required: true,

      validator: (_, value = '') => {
        if (!value || value.length > 20) {
          return Promise.reject('Please enter a postal code with less than 21 characters')
        }
        return Promise.resolve('')
      }
    },
    {
      label: 'Branch Address',
      name: 'address',
      required: true
    },
    {
      label: 'Contact Number',
      name: 'contact_number',
      required: true
    },
    {
      label: 'Is pick up service available',
      name: 'is_pickup_service_available',
      type: 'boolean',
      valueRender: (value) => value ? 'Yes' : 'No'
    },
    ...(isEditMode
      ? [{
          name: 'is_active',
          label: 'Is active',
          type: 'boolean',
          valueRender: (value) => value ? 'Yes' : 'No'
        }]
      : []),
    {
      label: 'Priority',
      name: 'priority',
      type: 'number',
      min: 1,
      max: 3,
      required: true,
      validator: (_, value) => {
        if ([1, 2, 3].includes(value)) {
          return Promise.resolve()
        }
        return Promise.reject('It can be 1, 2 or 3')
      }
    },
    ...(
      DISABLE_SERVICE_CENTER_BRAND_FLOW
        ? []
        : [{
            label: 'Brand',
            name: 'brand',
            type: 'multi-select',
            options: brandList,
            valueRender: (value) => Array.isArray(brandList) ? brandList.filter(({ id }) => value.includes(id)).map(({ name }) => name).join(', ') : 'N/A'
          }])
  ])
}
function CreateServiceCenterBranch ({
  form,
  brandList = [],
  getServiceCenterBrandList = () => {},
  getServiceCenterDetails = () => { },
  resetLoadingRedux = () => { },
  resetErrorRedux = () => { },
  resetServiceCenterRedux = () => { },
  getServiceCenterBranchDetailsMessage = '',
  createServiceCenterBranchLoading,
  createServiceCenterBranchMessage = '',
  createServiceCenterBranchError = false,

  updateServiceCenterBranchLoading,
  updateServiceCenterBranchMessage = '',
  updateServiceCenterBranchError = false,
  updateServiceCenterBranch = () => { },
  createServiceCenterBranch = () => { },
  getServiceCenterBranchDetails = () => { },
  getServiceCenterBranchDetailsError,
  getServiceCenterBranchDetailsLoading,
  getServiceCenterBranchDetailsData = {},
  serviceCenterDetail = {}
}) {
  const { getFieldDecorator } = form
  const params = useParams()
  const history = useHistory()

  const isEditMode = !(_.get(params, 'branchCode', '') === 'create-branch')
  const serviceCenterCode = _.get(params, 'id', '')

  useEffect(() => {
    getServiceCenterDetails({ id: serviceCenterCode })
  }, [serviceCenterCode])

  useEffect(() => {
    if (!DISABLE_SERVICE_CENTER_BRAND_FLOW) {
      getServiceCenterBrandList()
    }
  }, [])

  useEffect(() => {
    if (isEditMode) {
      const servicecenterCode = _.get(params, 'id', '')
      const branchCode = _.get(params, 'branchCode', '').toLowerCase()
      getServiceCenterBranchDetails({
        servicecenterCode,
        branchCode
      })
    }
    resetServiceCenterRedux(['updateServiceCenterBranchMessage', 'getServiceCenterBranchDetailsData'])
  }, [isEditMode, getServiceCenterBranchDetails, params, resetServiceCenterRedux])

  useEffect(() => {
    if (getServiceCenterBranchDetailsLoading === false) {
      if (getServiceCenterBranchDetailsError) {
        notification.error({
          message: getServiceCenterBranchDetailsMessage
        })
        history.goBack()
      }
      resetErrorRedux(['GET_SERVICE_CENTER_BRANCH_DETAIL'])
      resetLoadingRedux(['GET_SERVICE_CENTER_BRANCH_DETAIL'])
      resetServiceCenterRedux(['getServiceCenterBranchDetailsMessage'])
    }
  }, [
    history,
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    getServiceCenterBranchDetailsError,
    getServiceCenterBranchDetailsLoading,
    getServiceCenterBranchDetailsMessage
  ])

  useEffect(() => {
    if (createServiceCenterBranchLoading === false) {
      if (createServiceCenterBranchError) {
        notification.error({
          message: createServiceCenterBranchMessage
        })
      } else {
        notification.success({
          message: createServiceCenterBranchMessage
        })
        history.goBack()
      }
      resetErrorRedux(['CREATE_SERVICE_CENTER_BRANCH'])
      resetLoadingRedux(['CREATE_SERVICE_CENTER_BRANCH'])
      resetServiceCenterRedux(['createServiceCenterBranchMessage'])
    }
  }, [
    history,
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    createServiceCenterBranchError,
    createServiceCenterBranchMessage,
    createServiceCenterBranchLoading

  ])

  useEffect(() => {
    if (updateServiceCenterBranchLoading === false) {
      if (updateServiceCenterBranchError) {
        notification.error({
          message: updateServiceCenterBranchMessage
        })
      } else {
        notification.success({
          message: updateServiceCenterBranchMessage
        })
        history.goBack()
      }
      resetErrorRedux(['UPDATE_SERVICE_CENTER_BRANCH'])
      resetLoadingRedux(['UPDATE_SERVICE_CENTER_BRANCH'])
      resetServiceCenterRedux(['updateServiceCenterBranchMessage', 'getServiceCenterBranchDetailsData'])
    }
  }, [
    history,
    resetErrorRedux,
    resetLoadingRedux,
    resetServiceCenterRedux,
    updateServiceCenterBranchError,
    updateServiceCenterBranchMessage,
    updateServiceCenterBranchLoading
  ])

  const renderFormAttribute = ({ type, label, disabled, min, max, options = [], name }) => {
    switch (type) {
      case 'number':
        return (
          <InputNumber
            max={max}
            min={min}
            placeholder={`Enter ${label}`}
            style={{ width: '100%' }}
          />
        )
      case 'boolean':
        return <Switch />
      case 'multi-select':
        return (
          <Select
            showSearch
            data-testid={name}
            mode='multiple'
            placeholder={`Enter ${label}`}
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          >
            {options?.map(({ name, id }) => {
              return (
                <Option key={id} value={id}>
                  {name}
                </Option>
              )
            })}
          </Select>
        )
      default:
        return <Input placeholder={`Enter ${label}`} disabled={disabled} />
    }
  }

  const createServiceBranchHandler = (event) => {
    event.preventDefault()
    form.validateFields((err, values) => {
      if (err) return
      const VerifyData = (
        <div>
          {formDetails({ isEditMode, brandList }).map(({ name, label, valueRender }) => {
            return (
              <div key={name}>
                <span style={{ fontWeight: 900 }}>{label}</span>:
                <span style={{ paddingLeft: 10 }}>{
                  valueRender ? valueRender(values[name]) : values[name]
                }
                </span>
              </div>
            )
          })}
        </div>
      )
      Modal.confirm({
        title: 'Kindly verify the data that are you entering',
        content: VerifyData,
        okText: 'Confirm',
        onOk: () => {
          const serviceCenterCode = _.get(params, 'id', '')
          const payload = {
            service_center_code: serviceCenterCode,
            branch_code: values.branch_code,
            branch_data: {
              ...values,
              branch_code: undefined,
              is_pickup_service_available: values.is_pickup_service_available ? 'Yes' : 'No',
              brand: brandList.filter(({ id }) => values.brand.includes(id))
            }
          }
          if (isEditMode) {
            updateServiceCenterBranch(payload)
            return
          }
          createServiceCenterBranch(payload)
        }
      })
    })
  }

  const getInitValue = (formItem) => {
    const data = { ...getServiceCenterBranchDetailsData }
    const { type, name } = formItem
    if (name === 'brand') {
      return Array.isArray(data[name]) ? data[name].map(({ id }) => id) : []
    }
    if (type === 'boolean' && data[name]) return true
    if (type === 'boolean' && (data[name] !== null || data[name] !== undefined)) return false
    if (data[name] !== null || data[name] !== undefined) return data[name]
  }

  const onBackClickHandler = () => {
    history.goBack()
  }

  return (
    <CreateBranchContainer>
      <Button
        type='primary'
        onClick={onBackClickHandler}
      >
        Back
      </Button>
      <Spin spinning={!!getServiceCenterBranchDetailsLoading}>
        <FormContainer>
          <Form name='branch-details' layout='horizontal'>
            <Row gutter={24}>
              {
                formDetails({ isEditMode, brandList }).map((formItem) => {
                  const { name, label, disabled, type, helpText, required, validator, options } = formItem
                  return (
                    <Col span={12} key={name}>
                      <Item name={name} label={label} extra={helpText}>
                        {
                          getFieldDecorator(name, {
                            rules: [
                              { required: required, message: `${label} is required` },
                              ...(validator ? [{ validator }] : [])
                            ],
                            initialValue: getInitValue(formItem),
                            ...(type === 'boolean' ? { valuePropName: 'checked' } : {})
                          })(
                            renderFormAttribute({ type, disabled, label, options, name })
                          )
                        }
                      </Item>
                    </Col>
                  )
                })
              }
            </Row>
          </Form>
        </FormContainer>
      </Spin>

      <div>
        <Button
          type='primary'
          loading={createServiceCenterBranchLoading}
          onClick={createServiceBranchHandler}
        >
          Submit
        </Button>
      </div>
    </CreateBranchContainer>
  )
}

const FormWrapper = Form.create()(CreateServiceCenterBranch)

export default connect((state) => ({
  createServiceCenterBranchMessage: state.ServiceCenter.createServiceCenterBranchMessage,
  createServiceCenterBranchError: state.Error.CREATE_SERVICE_CENTER_BRANCH,
  createServiceCenterBranchLoading: state.Loading.CREATE_SERVICE_CENTER_BRANCH,

  updateServiceCenterBranchMessage: state.ServiceCenter.updateServiceCenterBranchMessage,
  updateServiceCenterBranchError: state.Error.UPDATE_SERVICE_CENTER_BRANCH,
  updateServiceCenterBranchLoading: state.Loading.UPDATE_SERVICE_CENTER_BRANCH,

  getServiceCenterBranchDetailsMessage: state.ServiceCenter.getServiceCenterBranchDetailsMessage,
  getServiceCenterBranchDetailsData: state.ServiceCenter.getServiceCenterBranchDetailsData,
  getServiceCenterBranchDetailsError: state.Error.GET_SERVICE_CENTER_BRANCH_DETAIL,
  getServiceCenterBranchDetailsLoading: state.Loading.GET_SERVICE_CENTER_BRANCH_DETAIL,
  serviceCenterDetail: state.ServiceCenter.getServiceCenterDetail,

  brandList: state.ServiceCenter.brandList
}),
{
  getServiceCenterBrandList,
  resetErrorRedux,
  resetLoadingRedux,
  getServiceCenterDetails,
  resetServiceCenterRedux,
  createServiceCenterBranch,
  updateServiceCenterBranch,
  getServiceCenterBranchDetails
}
)(FormWrapper)
